package ioc; import java.util.List; public final class AllowBlockLists{private final IocSet allow=new IocSet();private final IocSet block=new IocSet();public IocSet allow(){return allow;}public IocSet block(){return block;}public void addAllow(Ioc i){allow.add(i);}public void addBlock(Ioc i){block.add(i);}public boolean isAllowed(Ioc i){return allow.all().contains(i);}public boolean isBlocked(Ioc i){return block.all().contains(i);}public String summary(){return"allow="+allow.size()+" block="+block.size();}public void loadBlock(List<Ioc> list){block.addAll(list);}public void loadAllow(List<Ioc> list){allow.addAll(list);}}
